scwin.__hasClass = function(className) {
    if (WebSquare.wUnit.getJq("#widgetContainer1_widget0").hasClass(className)) {
        return true;
    }
    return false;
}
scwin.checkVal = function() {
    return WebSquare.wUnit.getObjById('widgetContainer1_widget0_title_text').innerText == 'widget0';
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행 후 widget0의 오른쪽 상단에 최대화, 최소화버튼을 클릭한다.
    //1. After running the sample file, click the Maximize and Minimize buttons at the top right of widget0.
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('widgetContainer1_widget0_title_btnMinimize').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.__hasClass('w2widget_minimized')", "true");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('widgetContainer1_widget0_title_btnMaximize').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.__hasClass('w2widget_maximized')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 11. 타이틀이 widget0의 위젯이 최대화, 최소화 되어진다.(이전에는 최대화, 최소화 기능이 없었음) 
    //1. Title Widget widget0 widget is maximized and minimized (Previously, it was not maximized, minimized)
    //Run and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
